    assert(all_your_base::convert(2, Digits{0, 1, 0, 1}, 10) == Digits{5});
    assert(all_your_base::convert(7, Digits{0, 6, 0}, 10) == Digits{4, 2});
    assert(all_your_base::convert(10, Digits{0, 0, 0}, 16).empty());
    assert(all_your_base::convert(2, Digits{}, 10).empty());

    assert(throws_invalid(1, Digits{}, 10));
    assert(throws_invalid(0, Digits{1}, 10));
    assert(throws_invalid(10, Digits{1}, 1));
    assert(throws_invalid(10, Digits{1}, 0));
