    assert(all_your_base::convert(big, Digits{big - 1}, big) == Digits{big - 1});
    assert(all_your_base::convert(big, Digits{big - 1}, 10) == big_decimal);
    assert(all_your_base::convert(10, big_decimal, big) == Digits{big - 1});

    return 0;
}
